<script setup>
import {computed,nextTick,ref} from 'vue';import {Heart,Search,ArrowLeft,PawPrint} from 'lucide-vue-next';import DogCard from './DogCard.vue';
const props=defineProps({compact:Boolean});const category=ref('all'),query=ref(''),selected=ref(null),saved=ref(new Set()),back=ref();
const pets=[['Луна','luna','home_search','2 года · спокойная, любит прогулки'],['Тоша','tosha','home_search','1 год · добрый и очень контактный'],['Рэй','rey','missed','3 года · потерялся возле парка'],['Майя','maya','found','4 года · найдена у остановки']].map(([name,slug,cat,description],i)=>({id:i+1,name,category:cat,description,city:{name:'Алматы'},preview_photo:{url:`/assets/demos/riyadom-${slug}.jpg`}}));
const filtered=computed(()=>pets.filter(p=>(category.value==='all'||p.category===category.value)&&p.name.toLowerCase().includes(query.value.toLowerCase())).slice(0,props.compact?2:4));
async function select(pet){selected.value=pet;await nextTick();back.value?.focus()}
function toggle(){const next=new Set(saved.value);next.has(selected.value.id)?next.delete(selected.value.id):next.add(selected.value.id);saved.value=next}
async function returnToCatalog(){const id=selected.value.id;selected.value=null;await nextTick();document.querySelector(`[data-pet-id="${id}"]`)?.focus()}
</script>
<template><div class="tailcare-demo" :class="{compact}"><header class="demo-topbar"><span class="demo-wordmark">TailCare <PawPrint :size="19"/></span><small>{{saved.size?`В избранном: ${saved.size}`:'Помощь рядом'}}</small></header><template v-if="!selected"><div class="pet-search"><Search :size="17"/><input v-model="query" aria-label="Имя питомца" placeholder="Найти друга по имени"/></div><div class="pet-filters" aria-label="Статус объявления"><button v-for="[key,label] in [['all','Все'],['home_search','Ищут дом'],['missed','Потерялись'],['found','Найдены']]" :key="key" :aria-pressed="category===key" @click="category=key">{{label}}</button></div><div v-if="filtered.length" class="pet-grid"><DogCard v-for="pet in filtered" :key="pet.id" :card="pet" :data-pet-id="pet.id" @select="select"/></div><div v-else class="pet-empty"><PawPrint :size="35"/><p>Никого не нашли. Попробуйте другое имя.</p><button class="demo-action" @click="query='';category='all'">Сбросить поиск</button></div></template><div v-else class="pet-detail"><button ref="back" class="pet-back" @click="returnToCatalog"><ArrowLeft :size="15"/> К каталогу</button><div class="pet-detail-content"><img :src="selected.preview_photo.url" :alt="selected.name"/><div><span>Алматы · Демо-объявление</span><h3>{{selected.name}}</h3><p>{{selected.description}}</p><button class="demo-action" :aria-pressed="saved.has(selected.id)" @click="toggle"><Heart :size="16" :fill="saved.has(selected.id)?'currentColor':'none'"/>{{saved.has(selected.id)?'В избранном':'Сохранить'}}</button></div></div></div><p class="demo-note">Поиск, фильтры и избранное работают прямо здесь</p></div></template>
